package edu.boun.edgecloudsim.research.counterfactual.evaluation.reporting;

import java.io.File;

import edu.boun.edgecloudsim.research.counterfactual.evaluation.config
        .EvaluationExperimentConfig;
import edu.boun.edgecloudsim.research.counterfactual.evaluation.directory
        .EvaluationDirectoryManager;

/**
 * Aggregates reports generated by EvaluationReportWriterTest.
 *
 * This smoke test expects one report set for 100 devices, iteration 1.
 */
public final class EvaluationReportAggregatorTest {

    private EvaluationReportAggregatorTest() {
    }

    public static void main(
            String[] args) {

        try {

            EvaluationExperimentConfig config =
                    EvaluationExperimentConfig
                    .builder()
                    .withExperimentId(
                            "STAGE_B_100_DEVICES")
                    .withStage(
                            edu.boun.edgecloudsim.research
                            .counterfactual.evaluation.config
                            .EvaluationStage.STAGE_B)
                    .withScenario(
                            "TWO_TIER_WITH_EO")
                    .withSimulationConfigFile(
                            new File(
                                    "scripts/counterfactual_offloading/"
                                    + "config/"
                                    + "default_config_stage_b_100.properties"))
                    .withEdgeDevicesFile(
                            new File(
                                    "scripts/counterfactual_offloading/"
                                    + "config/"
                                    + "edge_devices_research.xml"))
                    .withApplicationsFile(
                            new File(
                                    "scripts/counterfactual_offloading/"
                                    + "config/"
                                    + "applications_research.xml"))
                    .withOutputRoot(
                            new File(
                                    "evaluation_results"))
                    .withNetworkCondition(
                            edu.boun.edgecloudsim.research
                            .counterfactual.evaluation.config
                            .NetworkCondition.NORMAL)
                    .withSearchVariant(
                            edu.boun.edgecloudsim.research
                            .counterfactual.evaluation.config
                            .SearchVariant
                            .ADAPTIVE_PLUS_NEIGHBORHOOD)
                    .withDeviceCounts(
                            java.util.Collections
                            .singletonList(
                                    Integer.valueOf(
                                            100)))
                    .withIterationRange(
                            1,
                            1)
                    .withSchedulerPolicies(
                            EvaluationExperimentConfig
                            .defaultSchedulerPolicies())
                    .withObjectives(
                            EvaluationExperimentConfig
                            .defaultObjectives())
                    .withMaximumSelectedDecisionsPerObjective(
                            100)
                    .withMaximumRestorationDecisionsPerObjective(
                            100)
                    .withPpoModelId(
                            "PPO_BOOTSTRAP_V1")
                    .build();

            EvaluationDirectoryManager directoryManager =
                    new EvaluationDirectoryManager(
                            config);

            EvaluationReportAggregator.aggregate(
                    config,
                    directoryManager);

            System.out.println(
                    "EvaluationReportAggregator test passed.");

            System.out.println(
                    "Aggregate directory: "
                    + directoryManager
                    .getAggregateDirectory()
                    .getAbsolutePath());
        }
        catch(Exception exception) {

            exception.printStackTrace();

            throw new RuntimeException(
                    exception);
        }
    }
}